changeSet.sql:
DROP VIEW IF EXISTS reports.vwpayor;
ALTER TABLE public.payor DROP COLUMN IF EXISTS start_date, DROP COLUMN IF EXISTS expiry_date, DROP COLUMN IF EXISTS renewable, DROP COLUMN IF EXISTS allow_partial_coverage, DROP COLUMN IF EXISTS accept_copay, DROP COLUMN IF EXISTS accept_deductibles, DROP COLUMN IF EXISTS allow_package_pricing, DROP COLUMN IF EXISTS allow_drg_billing, DROP COLUMN IF EXISTS force_preapproval;
CREATE VIEW reports.vwpayor AS SELECT p.id, p.code, p.name, p.category, p.address, p.phone, p.email, p.contract_manager_contact, p.is_active, p.created_date, p.created_by, p.last_modified_by, p.last_modified_date, p.nphies_id, p.waseel_payer_id, p.tpa_nphies_id, p.is_waseel_enabled FROM public.payor p;
GRANT SELECT ON reports.vwpayor TO report_user;

rollback.sql:
DROP VIEW IF EXISTS reports.vwpayor;
ALTER TABLE public.payor ADD COLUMN IF NOT EXISTS start_date DATE, ADD COLUMN IF NOT EXISTS expiry_date DATE, ADD COLUMN IF NOT EXISTS renewable BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN IF NOT EXISTS allow_partial_coverage BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN IF NOT EXISTS accept_copay BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN IF NOT EXISTS accept_deductibles BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN IF NOT EXISTS allow_package_pricing BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN IF NOT EXISTS allow_drg_billing BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN IF NOT EXISTS force_preapproval BOOLEAN NOT NULL DEFAULT FALSE;
CREATE VIEW reports.vwpayor AS SELECT p.id, p.code, p.name, p.category, p.address, p.phone, p.email, p.contract_manager_contact, p.start_date, p.expiry_date, p.renewable, p.allow_partial_coverage, p.accept_copay, p.accept_deductibles, p.allow_package_pricing, p.allow_drg_billing, p.force_preapproval, p.is_active, p.created_date, p.created_by, p.last_modified_by, p.last_modified_date, p.nphies_id, p.waseel_payer_id, p.tpa_nphies_id, p.is_waseel_enabled FROM public.payor p;
GRANT SELECT ON reports.vwpayor TO report_user;
